// Terror Radius: players near a carrier hear a looping theme, in two layers.
// Generated by tools/terror_radius.py (change the values there).
import { system, world } from "@minecraft/server";
import { ActionFormData, ModalFormData } from "@minecraft/server-ui";

const CFG = __CONFIG__;
const PLAYER = "minecraft:player";
const HYSTERESIS = 0.5; // blocks: avoids restarting the audio when standing right on a border

// ------------------------------------------------------------ options
// World options live in world dynamic properties; each player keeps their own volume.
const DEFAULTS = { master: 100, outer: CFG.outer, inner: CFG.inner, self: true, debug: false };
let cached = null;

function options() {
  if (!cached) {
    cached = {};
    for (const [key, def] of Object.entries(DEFAULTS)) {
      const v = world.getDynamicProperty(`terror:${key}`);
      cached[key] = typeof v === typeof def ? v : def;
    }
  }
  return cached;
}

function setOption(key, value) {
  options()[key] = value;
  world.setDynamicProperty(`terror:${key}`, value);
}

function ownVolume(player) {
  const v = player.getDynamicProperty("terror:volume");
  return typeof v === "number" ? v : 100;
}

// ------------------------------------------------------------ who counts
// Only players and test dummies. Nothing else can carry or trigger the terror radius.
function isSpectator(player) {
  return String(player.getGameMode()).toLowerCase() === "spectator";
}

function isCarrier(entity) {
  return entity.hasTag(CFG.tag);
}

function dummies(players) {
  const dims = new Map();
  for (const name of ["overworld", "nether", "the_end"]) {
    try {
      const d = world.getDimension(name);
      dims.set(d.id, d);
    } catch {}
  }
  for (const p of players) dims.set(p.dimension.id, p.dimension);
  const out = [];
  for (const d of dims.values()) {
    try {
      out.push(...d.getEntities({ type: CFG.dummy }));
    } catch {}
  }
  return out;
}

function displayName(entity) {
  return entity.typeId === PLAYER ? entity.name : "Dummy";
}

function setCarrier(entity, on) {
  if (on) entity.addTag(CFG.tag);
  else entity.removeTag(CFG.tag);
  if (entity.typeId === CFG.dummy) entity.nameTag = on ? "§cDummy §7[Terror Radius]" : "Dummy";
}

function distance(a, b) {
  return Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
}

// ------------------------------------------------------------ audio loop
// The game cannot loop a sound by itself, so each layer is played again when it ends.
const playing = new Map(); // player id -> { layer, volume, endsAt, distance }

function stop(player, layer) {
  try {
    player.runCommand(`stopsound @s ${CFG.layers[layer - 1].sound}`);
  } catch {}
}

function start(player, st) {
  const def = CFG.layers[st.layer - 1];
  player.playSound(def.sound, { volume: st.volume });
  st.endsAt = Date.now() + def.seconds * 1000 - CFG.overlapMs;
}

function apply(player, layer, volume, dist) {
  let st = playing.get(player.id);
  if (!st) playing.set(player.id, (st = { layer: 0, volume: 0, endsAt: 0, distance: Infinity }));
  st.distance = dist;
  if (st.layer !== layer || (layer && st.volume !== volume)) {
    if (st.layer) stop(player, st.layer);
    st.layer = layer;
    st.volume = volume;
    if (layer) start(player, st);
  } else if (layer && Date.now() >= st.endsAt) {
    start(player, st);
  }
}

function layerFor(dist, current, o) {
  const inner = o.inner + (current === 2 ? HYSTERESIS : 0);
  const outer = o.outer + (current >= 1 ? HYSTERESIS : 0);
  return dist <= inner ? 2 : dist <= outer ? 1 : 0;
}

function tick() {
  const o = options();
  const players = world.getAllPlayers();
  const bodies = []; // every player (not spectators) and every dummy
  const carrying = new Set();
  for (const p of players) {
    if (isSpectator(p)) continue;
    const carrier = isCarrier(p);
    if (carrier) carrying.add(p.id);
    bodies.push({ id: p.id, dim: p.dimension.id, loc: p.location, carrier });
  }
  for (const d of dummies(players)) {
    bodies.push({ id: d.id, dim: d.dimension.id, loc: d.location, carrier: isCarrier(d) });
  }

  for (const p of players) {
    try {
      // A listener hears the nearest carrier; a carrier (if the option is on) hears it
      // while anyone is inside their own radius.
      const any = o.self && carrying.has(p.id);
      const dim = p.dimension.id;
      const loc = p.location;
      let best = Infinity;
      for (const b of bodies) {
        if (b.id === p.id || b.dim !== dim || !(b.carrier || any)) continue;
        const d = distance(loc, b.loc);
        if (d < best) best = d;
      }
      const volume = (o.master * ownVolume(p)) / 10000;
      const current = playing.get(p.id)?.layer ?? 0;
      apply(p, volume > 0 ? layerFor(best, current, o) : 0, volume, best);
      if (o.debug && system.currentTick % 10 === 0) hud(p, best);
    } catch {}
  }
}

function hud(player, dist) {
  const layer = playing.get(player.id)?.layer ?? 0;
  const who = isCarrier(player) ? "§cportador§7 · " : "";
  const near = dist === Infinity ? "nadie cerca" : `${dist.toFixed(1)} bloques`;
  const text = layer ? `§cTerror Radius §fcapa ${layer}` : "§8Terror Radius: silencio";
  player.onScreenDisplay.setActionBar(`${who}${text} §7· ${near}`);
}

system.runInterval(() => {
  try {
    tick();
  } catch {}
}, 1);

world.afterEvents.playerLeave.subscribe((ev) => playing.delete(ev.playerId));

world.afterEvents.playerSpawn.subscribe((ev) => {
  if (!ev.initialSpawn) return;
  // nothing can be left playing from a previous session
  playing.delete(ev.player.id);
  for (let layer = 1; layer <= CFG.layers.length; layer++) stop(ev.player, layer);
});

// ------------------------------------------------------------ selector item
const lastUse = new Map(); // player id -> tick (some uses arrive twice)

function toggle(user, target) {
  const on = !isCarrier(target);
  setCarrier(target, on);
  const name = displayName(target);
  user.sendMessage(on ? `§c${name} ahora tiene Terror Radius.` : `§7${name} ya no tiene Terror Radius.`);
  if (on && target.typeId === PLAYER && target.id !== user.id) {
    target.sendMessage("§cAhora tienes Terror Radius.");
  }
}

function lookedAt(player) {
  try {
    for (const hit of player.getEntitiesFromViewDirection({ maxDistance: CFG.reach })) {
      const e = hit.entity;
      if (e.id !== player.id && (e.typeId === PLAYER || e.typeId === CFG.dummy)) return e;
    }
  } catch {}
  return undefined;
}

world.afterEvents.itemUse.subscribe((ev) => {
  if (ev.itemStack?.typeId !== CFG.item) return;
  const player = ev.source;
  const last = lastUse.get(player.id);
  if (last !== undefined && system.currentTick - last <= 4) return;
  lastUse.set(player.id, system.currentTick);
  // Looking at a player or a dummy: give / remove it directly. Sneaking: always the menu.
  const target = player.isSneaking ? undefined : lookedAt(player);
  if (target) toggle(player, target);
  else mainMenu(player);
});

// ------------------------------------------------------------ menus
function show(form, player, then) {
  form
    .show(player)
    .then((res) => {
      if (!res.canceled) then(res);
    })
    .catch(() => {});
}

function candidates() {
  const players = world.getAllPlayers();
  return [...players, ...dummies(players)];
}

function mainMenu(player) {
  const o = options();
  const all = candidates();
  const active = all.filter(isCarrier).length;
  const form = new ActionFormData()
    .title("Terror Radius")
    .body(
      `Capa 1: de ${o.outer} a ${o.inner} bloques.\nCapa 2: de ${o.inner} a 0 bloques.\n` +
        "Usa el selector mirando a un jugador o dummy para dárselo o quitárselo."
    )
    .button(`Elegir quién lo tiene\n§8${active} activo(s)`)
    .button(`Mi volumen\n§8${ownVolume(player)} %`)
    .button("Opciones")
    .button("Invocar dummy de prueba")
    .button("Quitar todos los dummies");
  show(form, player, (res) => {
    if (res.selection === 0) carriersMenu(player);
    else if (res.selection === 1) volumeMenu(player);
    else if (res.selection === 2) optionsMenu(player);
    else if (res.selection === 3) summonDummy(player);
    else if (res.selection === 4) removeDummies(player);
  });
}

function carriersMenu(player) {
  const all = candidates();
  const form = new ActionFormData().title("¿Quién tiene Terror Radius?").body("Toca un nombre para ponerlo o quitarlo.");
  for (const e of all) {
    const far = e.id === player.id ? "tú" : e.dimension.id === player.dimension.id
      ? `${Math.round(distance(e.location, player.location))} bloques` : "otra dimensión";
    form.button(`${isCarrier(e) ? "§4[ACTIVO] " : ""}${displayName(e)}\n§8${far}`);
  }
  form.button("Quitárselo a todos");
  form.button("Volver");
  show(form, player, (res) => {
    if (res.selection === all.length + 1) return mainMenu(player);
    if (res.selection === all.length) {
      for (const e of all) if (e.isValid && isCarrier(e)) setCarrier(e, false);
      player.sendMessage("§7Nadie tiene Terror Radius.");
    } else {
      const e = all[res.selection];
      if (e?.isValid) toggle(player, e);
    }
    carriersMenu(player);
  });
}

function volumeMenu(player) {
  const form = new ModalFormData()
    .title("Mi volumen")
    .slider("Volumen del Terror Radius para ti (%)", 0, 100, { valueStep: 5, defaultValue: ownVolume(player) })
    .submitButton("Guardar");
  show(form, player, (res) => {
    const value = Number(res.formValues[0]);
    player.setDynamicProperty("terror:volume", value);
    player.sendMessage(`§7Tu volumen del Terror Radius: §f${value} %`);
  });
}

function optionsMenu(player) {
  const o = options();
  const form = new ModalFormData()
    .title("Opciones del Terror Radius")
    .slider("Volumen general (%)", 0, 100, { valueStep: 5, defaultValue: o.master })
    .slider("Radio de la capa 1 (bloques)", 4, 64, { valueStep: 1, defaultValue: o.outer })
    .slider("Radio de la capa 2 (bloques)", 1, 60, { valueStep: 1, defaultValue: o.inner })
    .toggle("El portador también lo oye cuando alguien entra en su radio", { defaultValue: o.self })
    .toggle("Mostrar capa y distancia en pantalla (para probar)", { defaultValue: o.debug })
    .submitButton("Guardar");
  show(form, player, (res) => {
    const [master, outer, innerAsked, self, debug] = res.formValues;
    const inner = Math.min(Number(innerAsked), Number(outer) - 1);
    setOption("master", Number(master));
    setOption("outer", Number(outer));
    setOption("inner", inner);
    setOption("self", Boolean(self));
    setOption("debug", Boolean(debug));
    if (inner !== Number(innerAsked)) {
      player.sendMessage(`§7La capa 2 tiene que ser más pequeña que la capa 1: se queda en ${inner} bloques.`);
    }
    player.sendMessage(`§7Opciones guardadas: capa 1 hasta ${outer} bloques, capa 2 hasta ${inner}.`);
  });
}

function summonDummy(player) {
  try {
    const dummy = player.dimension.spawnEntity(CFG.dummy, player.location);
    dummy.nameTag = "Dummy";
    player.sendMessage("§7Dummy invocado. Cuenta como un jugador para el Terror Radius.");
  } catch {
    player.sendMessage("§cNo se pudo invocar el dummy aquí.");
  }
}

function removeDummies(player) {
  const all = dummies(world.getAllPlayers());
  for (const d of all) {
    try {
      d.remove();
    } catch {}
  }
  player.sendMessage(`§7Dummies quitados: ${all.length}.`);
}
